import{_ as i,C as r,o as a,c as o,a7 as e,b as h,w as n,a as s,E as u,a8 as l}from"./chunks/framework.BCbKzsgW.js";const f=JSON.parse('{"title":"文件处理：上传完成、异步转码与批量资源控制","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/task-scheduling/scenarios/file-processing.md","filePath":"development/common/task-scheduling/scenarios/file-processing.md","lastUpdated":1793441194000}'),p={name:"development/common/task-scheduling/scenarios/file-processing.md"};function c(E,t,g,A,b,B){const d=r("Mermaid");return a(),o("div",null,[t[1]||(t[1]=e('<h1 id="wen-jian-chu-lishang-chuan-wan-chengyi-bu-zhuan-ma-yu-pi-liang-zi-yuan-kong-zhi" tabindex="-1">文件处理：上传完成、异步转码与批量资源控制 <a class="header-anchor" href="#wen-jian-chu-lishang-chuan-wan-chengyi-bu-zhuan-ma-yu-pi-liang-zi-yuan-kong-zhi" aria-label="Permalink to &quot;文件处理：上传完成、异步转码与批量资源控制&quot;">​</a></h1><p>视频转码应在文件完成上传并校验后触发。创建上传地址或收到第一块数据时，源文件可能仍不完整；用户刷新或登录页面只能查询进度，不能反复创建新的转码。</p><p>示例把同一源文件版本转成多种输出格式，允许格式任务独立失败与重试。</p><h2 id="cong-shang-chuan-jie-kou-tui-dao-hou-tai-chu-li" tabindex="-1">从上传接口推导后台处理 <a class="header-anchor" href="#cong-shang-chuan-jie-kou-tui-dao-hou-tai-chu-li" aria-label="Permalink to &quot;从上传接口推导后台处理&quot;">​</a></h2><p>假设一个小文件格式转换只需很短时间，容量可控且请求超时预算足够，同步处理可以成立。需求变成上传大型视频、用户随时离开、处理持续数分钟时，请求生命周期就无法承担整个处理过程。</p><table tabindex="0"><thead><tr><th>候选方案</th><th>适合什么条件</th><th>需要处理的代价</th></tr></thead><tbody><tr><td>上传请求内转换</td><td>耗时短、资源上界可控</td><td>请求长占用，断开后的结果不确定</td></tr><tr><td>请求返回后启动内存协程</td><td>工作可以丢失或有外部重建依据</td><td>进程重启、限流、进度持久化</td></tr><tr><td>持久化运行与输出任务</td><td>需要独立恢复、跟踪与资源控制</td><td>源版本、任务领取、产物发布和清理</td></tr></tbody></table><p>本篇选择第三种。拆分的最小单位是可独立确认的输出格式，而不是无条件把一整份文件的所有处理捆在一次重试里。对于必须共享一次昂贵解码的处理流水，也可以改用单运行多阶段，但要相应设计阶段检查点。</p><h2 id="shang-chuan-que-renzhuan-ma-yu-chan-wu-fa-bu-shi-xu" tabindex="-1">上传确认、转码与产物发布时序 <a class="header-anchor" href="#shang-chuan-que-renzhuan-ma-yu-chan-wu-fa-bu-shi-xu" aria-label="Permalink to &quot;上传确认、转码与产物发布时序&quot;">​</a></h2><p>对象写入与数据库发布不在同一个事务里。暂存产物可以已经存在，但未取得发布资格时不对用户作为正式结果开放。</p>',9)),(a(),h(l,null,{default:n(()=>[u(d,{id:"mermaid-74",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20A%20as%20%E5%AE%8C%E6%88%90%E4%B8%8A%E4%BC%A0%E6%8E%A5%E5%8F%A3%0A%20%20%20%20participant%20D%20as%20%E6%95%B0%E6%8D%AE%E5%BA%93%0A%20%20%20%20participant%20W%20as%20%E8%BD%AC%E7%A0%81%20Worker%0A%20%20%20%20participant%20S%20as%20%E5%AF%B9%E8%B1%A1%E5%AD%98%E5%82%A8%0A%20%20%20%20A-%3E%3ES%3A%20%E6%A0%B8%E5%AF%B9%E6%BA%90%E5%AF%B9%E8%B1%A1%E7%89%88%E6%9C%AC%E4%B8%8E%E5%AE%8C%E6%95%B4%E6%80%A7%0A%20%20%20%20S--%3E%3EA%3A%20%E8%BF%94%E5%9B%9E%E5%AF%B9%E8%B1%A1%E4%BA%8B%E5%AE%9E%0A%20%20%20%20A-%3E%3ED%3A%20%E5%90%8C%E4%BA%8B%E5%8A%A1%E7%99%BB%E8%AE%B0%E6%BA%90%E7%89%88%E6%9C%AC%3Cbr%3E%E5%88%9B%E5%BB%BA%E8%BF%90%E8%A1%8C%E4%B8%8E%E6%A0%BC%E5%BC%8F%E4%BB%BB%E5%8A%A1%0A%20%20%20%20W-%3E%3ED%3A%20%E6%8C%89%E8%B5%84%E6%BA%90%E9%A2%86%E5%8F%96%E4%BB%BB%E5%8A%A1%3Cbr%3E%E5%8F%96%E5%BE%97%E6%9C%AC%E6%AC%A1%20token%0A%20%20%20%20W-%3E%3ES%3A%20%E8%AF%BB%E5%8F%96%E7%A1%AE%E5%88%87%E6%BA%90%E7%89%88%E6%9C%AC%0A%20%20%20%20W-%3E%3EW%3A%20%E8%BD%AC%E7%A0%81%E5%B9%B6%E6%A0%A1%E9%AA%8C%0A%20%20%20%20W-%3E%3ES%3A%20%E5%86%99%E5%85%A5%E6%9C%AC%E6%AC%A1%E6%9A%82%E5%AD%98%E4%BA%A7%E7%89%A9%0A%20%20%20%20W-%3E%3ED%3A%20%E6%A0%B8%E5%AF%B9%20token%E3%80%81%E6%BA%90%E7%89%88%E6%9C%AC%E4%B8%8E%E5%8F%96%E6%B6%88%E7%8A%B6%E6%80%81%0A%20%20%20%20alt%20%E4%BB%8D%E6%9C%89%E5%8F%91%E5%B8%83%E8%B5%84%E6%A0%BC%0A%20%20%20%20%20%20%20%20W-%3E%3ED%3A%20%E5%8F%91%E5%B8%83%E6%A0%BC%E5%BC%8F%E7%BB%93%E6%9E%9C%3Cbr%3E%E8%BE%BE%E5%88%B0%E6%9D%A1%E4%BB%B6%E5%90%8E%E4%BF%9D%E5%AD%98%E5%8F%AF%E7%94%A8%E9%80%9A%E7%9F%A5%0A%20%20%20%20else%20%E6%97%A7%E5%B0%9D%E8%AF%95%E6%88%96%E6%96%87%E4%BB%B6%E5%B7%B2%E6%92%A4%E9%94%80%0A%20%20%20%20%20%20%20%20W-%3E%3ED%3A%20%E4%B8%8D%E5%8F%91%E5%B8%83%3Cbr%3E%E7%99%BB%E8%AE%B0%E6%9A%82%E5%AD%98%E5%9B%9E%E6%94%B6%E5%AF%B9%E8%B1%A1%0A%20%20%20%20end%0A"})]),fallback:n(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e(`<p>多个格式可以独立执行与恢复。通知阶段读取已发布的文件版本，不以某个子进程已经退出作为整份文件可用的唯一依据。</p><h2 id="wen-jian-chu-li-xu-qiu-yu-wan-cheng-biao-zhun" tabindex="-1">文件处理需求与完成标准 <a class="header-anchor" href="#wen-jian-chu-li-xu-qiu-yu-wan-cheng-biao-zhun" aria-label="Permalink to &quot;文件处理需求与完成标准&quot;">​</a></h2><p>示例要求上传完成后生成低清预览与高清版本，预览先完成时允许用户先看，全部必需格式完成后才标记整份文件 ready。产品也可以选择必须全部成功，关键是明确发布条件。</p><table tabindex="0"><thead><tr><th>需求</th><th>示例决策</th><th>开发约束</th></tr></thead><tbody><tr><td>谁能上传</td><td>按租户和用户控制大小、数量与资源预算</td><td>上传会话与配额记录</td></tr><tr><td>上传后何时开始</td><td>完成合并并通过源文件校验</td><td>完成接口和存储事件共同核对</td></tr><tr><td>什么叫可用</td><td>必需输出通过校验且正式结果已发布</td><td>不把进程退出码当唯一成功标准</td></tr><tr><td>谁能取消</td><td>文件所有者与授权操作员</td><td>取消请求与源版本关联</td></tr><tr><td>重做后是否覆盖旧版本</td><td>新处理版本完整后切换</td><td>产物指针条件更新</td></tr></tbody></table><h2 id="chu-fa-qian-que-ren-yuan-wen-jian" tabindex="-1">触发前确认源文件 <a class="header-anchor" href="#chu-fa-qian-que-ren-yuan-wen-jian" aria-label="Permalink to &quot;触发前确认源文件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事实</th><th>需要确认什么</th></tr></thead><tbody><tr><td>上传完成</td><td>分片合并已完成，对象能够读取</td></tr><tr><td>文件身份</td><td>对象键、版本或不可变内容标识稳定</td></tr><tr><td>业务登记</td><td>文件属于正确用户，大小与格式校验通过</td></tr><tr><td>处理要求</td><td>使用哪个转码参数版本、哪些输出格式</td></tr></tbody></table><p>对象存储通知可能重复或乱序。以 S3 为例，官方明确说明事件至少投递一次且不保证顺序，见<a href="https://docs.aws.amazon.com/AmazonS3/latest/userguide/notification-how-to-event-types-and-destinations.html#event-ordering-and-duplicate-events" target="_blank" rel="noreferrer">事件顺序与重复说明</a>。</p><p>任务键可以采用 <code>file_id + source_version + profile_version + output_format</code>。同一路径后来上传的新内容不能继续沿用旧任务身份。</p><h2 id="shu-ju-jie-gou-yu-ye-wu-jie-kou" tabindex="-1">数据结构与业务接口 <a class="header-anchor" href="#shu-ju-jie-gou-yu-ye-wu-jie-kou" aria-label="Permalink to &quot;数据结构与业务接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>记录</th><th>关键字段与约束</th></tr></thead><tbody><tr><td><code>upload_sessions</code></td><td>用户、源对象身份、预期大小、完成状态、请求键</td></tr><tr><td><code>file_versions</code></td><td>文件、源版本、校验摘要、登记状态、删除标记</td></tr><tr><td><code>processing_runs</code></td><td>源版本、参数版本、所需格式、取消状态</td></tr><tr><td><code>processing_outputs</code></td><td>运行、格式、尝试 token、暂存产物、校验结果、发布指针</td></tr><tr><td><code>storage_inbox</code></td><td>存储来源与事件身份、原始内容、关联状态</td></tr></tbody></table><p>产物可用通知复用<a href="./batch-design.html#gong-yong-zhi-xing-yu-tong-zhi-yue-ding">通知意图与渠道投递约定</a>：意图绑定处理运行及发布版本，渠道记录保存每个目标的请求身份、提交时间和结果。通知失败只重试相应投递，不重新转码或重复发布产物。</p><p>业务接口可以划分为开始上传、确认完成、查询处理进度、请求取消和创建重新处理版本。重复完成请求返回同一运行，不再次创建所有输出任务；重新处理请求必须明确参数版本和请求幂等键。</p><p>下载接口同时校验文件归属与当前可见版本。业务表中的对象地址不应直接成为永久公开访问凭据。</p><h2 id="shang-chuan-deng-ji-yu-ren-wu-chuang-jian" tabindex="-1">上传登记与任务创建 <a class="header-anchor" href="#shang-chuan-deng-ji-yu-ren-wu-chuang-jian" aria-label="Permalink to &quot;上传登记与任务创建&quot;">​</a></h2><p>应用确认上传完成后，在业务数据库中保存文件版本与转码任务。对象已经存在、数据库登记却失败时，保留可重试的完成流程，并定期识别孤立对象。</p><p>如果存储事件先于业务登记到达，消费者可以记录待关联事件，稍后核对；不要因为暂时查不到文件记录，就永久确认并丢弃唯一的触发依据。</p><p>Outbox 只能覆盖数据库内部的原子提交，不能让对象存储与数据库自动变成一个事务。</p><h2 id="wan-cheng-shang-chuan-de-chu-li-liu-cheng" tabindex="-1">完成上传的处理流程 <a class="header-anchor" href="#wan-cheng-shang-chuan-de-chu-li-liu-cheng" aria-label="Permalink to &quot;完成上传的处理流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>完成 API 或存储事件触发核对：</span></span>
<span class="line"><span>  验证来源、上传会话身份、对象版本与完整性</span></span>
<span class="line"><span>  在事务外完成必要的对象读取或校验</span></span>
<span class="line"><span>  BEGIN</span></span>
<span class="line"><span>    锁定上传会话，确认没有取消且源版本仍相同</span></span>
<span class="line"><span>    幂等保存 file_version 与 processing_run</span></span>
<span class="line"><span>    为必需输出格式创建独立任务</span></span>
<span class="line"><span>    更新上传完成状态</span></span>
<span class="line"><span>  COMMIT</span></span></code></pre></div><p>存储事件先到时，把事件持久化到待关联记录；业务登记先到时，保留等待对象确认的状态。核对任务让两条路径最终接上，不能让一次暂时查询失败变成永久漏处理。</p><h2 id="1000-ge-shi-pin-tong-shi-shang-chuan" tabindex="-1">1000 个视频同时上传 <a class="header-anchor" href="#1000-ge-shi-pin-tong-shi-shang-chuan" aria-label="Permalink to &quot;1000 个视频同时上传&quot;">​</a></h2><p>1000 个 10 MB 短视频与 1000 个 5 GB 长视频，不能采用相同的并发预估。队列长度之外，还要估算总时长、输入字节、预计 CPU/GPU 时间、临时磁盘与输出大小。</p><p>可以按轻重任务划分资源池，按用户限制并发，给交互式短任务保留容量。Worker 根据可用资源领取任务，不能先领取全部 1000 条，再让它们在内存里等待直到租约过期。</p><p>通知渠道与转码资源分别限流。把更多通知 Worker 加进去，不会提高 GPU 转码吞吐。</p><h2 id="worker-de-zhi-xing-bian-jie" tabindex="-1">Worker 的执行边界 <a class="header-anchor" href="#worker-de-zhi-xing-bian-jie" aria-label="Permalink to &quot;Worker 的执行边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>行为</th><th>失败恢复</th></tr></thead><tbody><tr><td>准备</td><td>领取与资源匹配的任务，核对源版本、取消和配额</td><td>暂时无资源则不大量预领取</td></tr><tr><td>处理</td><td>使用本次尝试的隔离工作目录，持续检查截止时间</td><td>超时停止子进程并记录退出结果</td></tr><tr><td>保存</td><td>暂存输出和校验摘要，确认大小、格式与可读性</td><td>部分产物按尝试身份清理</td></tr><tr><td>发布</td><td>事务中校验当前领取 token、源版本与运行状态</td><td>失去资格则不发布旧产物</td></tr><tr><td>收尾</td><td>更新格式结果与文件可用条件，保存通知</td><td>通知失败独立恢复</td></tr></tbody></table><p>续租失败只改变数据库所有权，不会自动停止转码进程。Worker 要主动结束或隔离旧执行，并以发布时的 token 检查防止迟到结果覆盖。</p><h2 id="bu-fen-cheng-gong-he-jie-guo-fa-bu" tabindex="-1">部分成功和结果发布 <a class="header-anchor" href="#bu-fen-cheng-gong-he-jie-guo-fa-bu" aria-label="Permalink to &quot;部分成功和结果发布&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>源版本通过校验</span></span>
<span class="line"><span>  → 创建各输出格式任务</span></span>
<span class="line"><span>  → 输出写入本次尝试的暂存位置</span></span>
<span class="line"><span>  → 校验产物完整性</span></span>
<span class="line"><span>  → 条件更新该格式的正式结果指针</span></span>
<span class="line"><span>  → 所需格式达到发布条件后，通知文件可用</span></span></code></pre></div><p>重试使用独立暂存产物，只有通过版本与所有权检查后才发布，避免旧 Worker 恢复后覆盖新结果。两个格式成功、一个失败时，按产品规则决定部分可用，失败格式单独重试。</p><p>暂存地址回答“本次尝试写到了哪里”，正式指针回答“用户可以读取哪份结果”。外部存储写入可能已经完成，而发布事务仍然失败；分开两者，才能回收无人引用的产物，并阻止把半成品直接暴露给用户。</p><h2 id="shan-chuqu-xiao-yu-hui-fu" tabindex="-1">删除、取消与恢复 <a class="header-anchor" href="#shan-chuqu-xiao-yu-hui-fu" aria-label="Permalink to &quot;删除、取消与恢复&quot;">​</a></h2><p>用户删除文件后，运行中的任务可能仍持有源对象。处理器应在关键阶段检查删除或取消状态，停止发布；临时产物通过有范围的清理任务回收。</p><p>任务重试需要确认源版本仍存在、参数仍有效，并区分暂时读失败与永久格式不支持。长期失败不能无限占用昂贵资源。</p><p>兜底扫描核对“上传已登记但没有任务”“任务成功却缺少可用产物”“暂存对象无人引用”。完成通知按文件可用版本去重，用户离线也不影响处理继续进行。</p><h2 id="yi-ci-bu-fen-cheng-gong-yu-jiu-chang-shi-hui-fu" tabindex="-1">一次部分成功与旧尝试恢复 <a class="header-anchor" href="#yi-ci-bu-fen-cheng-gong-yu-jiu-chang-shi-hui-fu" aria-label="Permalink to &quot;一次部分成功与旧尝试恢复&quot;">​</a></h2><p>假设文件 F6 的源版本为 3，处理运行 P12 要生成预览和高清两个格式：</p><table tabindex="0"><thead><tr><th>动作</th><th>处理与产物记录</th><th>对外结果</th></tr></thead><tbody><tr><td>完成事件重复到达</td><td>仍是同一源版本与参数版本的 P12</td><td>不额外创建第二轮全部任务</td></tr><tr><td>预览校验并发布成功</td><td>preview 指向本轮有效产物</td><td>按示例规则允许预览</td></tr><tr><td>高清尝试 token 8 停顿超租约</td><td>重新领取得到 token 9</td><td>高清仍未就绪</td></tr><tr><td>token 9 生成并发布高清</td><td>正式结果关联有效尝试</td><td>满足必需格式后整体 ready</td></tr><tr><td>token 8 恢复并写出旧暂存对象</td><td>发布检查失败，保留待回收记录</td><td>不覆盖 token 9 的结果</td></tr></tbody></table><p>如果用户此时删除 F6，发布事务还要检查删除状态。只检查源版本相同不足以授权发布，因为同一源版本也可能已经被撤销。</p><p>这个案例可以迁移到图片缩略图、导入文件和文档解析：先识别输入版本，再定义可独立确认的结果，最后控制谁有权发布。</p><h2 id="yan-shou-yu-pai-cha-yi-ju" tabindex="-1">验收与排查依据 <a class="header-anchor" href="#yan-shou-yu-pai-cha-yi-ju" aria-label="Permalink to &quot;验收与排查依据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>应断言的结果</th></tr></thead><tbody><tr><td>完成上传请求与对象事件各到达两次</td><td>只生成同一源版本的必需格式任务</td></tr><tr><td>对象完成但业务登记暂时不存在</td><td>待关联事件保留，核对后可继续</td></tr><tr><td>三个格式中一个失败</td><td>成功格式不重算，整份 ready 按约定判断</td></tr><tr><td>旧尝试在新尝试发布后结束</td><td>token 与版本检查阻止旧结果替换</td></tr><tr><td>删除与发布同时发生</td><td>发布事务核对删除状态，旧链接无权访问</td></tr><tr><td>1000 个重任务同时到来</td><td>资源池、租户配额与临时磁盘都受控</td></tr></tbody></table><p>每次尝试记录输入字节、媒体时长、执行资源、输出格式、退出原因与产物摘要。积压容量按预计工作量衡量，同时观察待处理年龄，不能只看任务条数。</p><h2 id="teng-xun-yun-mei-ti-fu-wu-de-hui-diao-yu-jie-guo-bu-cha" tabindex="-1">腾讯云媒体服务的回调与结果补查 <a class="header-anchor" href="#teng-xun-yun-mei-ti-fu-wu-de-hui-diao-yu-jie-guo-bu-cha" aria-label="Permalink to &quot;腾讯云媒体服务的回调与结果补查&quot;">​</a></h2><p>腾讯云点播的<a href="https://cloud.tencent.com/document/product/266/33781" target="_blank" rel="noreferrer">回调设置</a>区分普通 HTTP 回调与内置队列供应用拉取消费的可靠回调。另一个产品——腾讯云媒体处理——在<a href="https://cloud.tencent.com/document/product/862/37049" target="_blank" rel="noreferrer">任务配置常见问题</a>中说明，未收到转码回调可能源于配置错误或任务积压；已成功提交的 API 任务可以通过任务查询接口检查进度。两份资料对应不同产品，接入时应分别核对协议。</p><p>应用因此需要保存外部任务 ID、源文件版本、提交时间和最后核对时间。本文建议先接收事件并去重，再按任务身份更新格式结果；长时间没有事件时发起限速补查。没有收到回调不能直接判定转码失败，更不能每次超时都重新提交昂贵的转码任务。</p><p>1000 个视频同时处理时，应把处理并发、事件消费能力与补查频率分别限制。若大量任务停在处理中，先区分执行积压和通知积压，再安排恢复。可靠回调改善的是结果通知路径，业务仍需处理重复结果、源文件撤销和正式产物发布条件；上述字段和恢复策略属于本文的接入设计建议。</p><h2 id="huo-shan-yin-qing-shi-pin-dian-boshang-chuan-cheng-gong-hou-yuan-xin-xi-reng-ke-neng-wei-jiu-xu" tabindex="-1">火山引擎视频点播：上传成功后元信息仍可能未就绪 <a class="header-anchor" href="#huo-shan-yin-qing-shi-pin-dian-boshang-chuan-cheng-gong-hou-yuan-xin-xi-reng-ke-neng-wei-jiu-xu" aria-label="Permalink to &quot;火山引擎视频点播：上传成功后元信息仍可能未就绪&quot;">​</a></h2><p>火山引擎的<a href="https://docs.volcengine.com/docs/video-on-demand/event-notification-faq?lang=zh" target="_blank" rel="noreferrer">事件通知常见问题</a>说明：超大文件可能先完成上传，再抽取元信息，上传完成回调中的文件信息因而可能为空；回调失败会有限重试，耗尽后会丢弃通知。上传完成、元信息可用与转码完成需要分开判断。</p><p>本文建议保存源文件已上传、元信息待就绪、处理已提交、产物待发布等阶段。回调缺少时长或编码信息时，不应仅据此判定文件损坏，也不能立即发布给需要这些信息的下游。保存外部身份后，按对应 API 支持的查询方式补齐证据，并为长期未就绪任务设置超时处置。不能假设供应商会永久重推丢失通知。</p><h2 id="mei-tuan-liu-shui-xian-yin-qingling-qu-cheng-gong-yu-zhi-xing-kai-shi-zhi-jian-huan-you-chuang-kou" tabindex="-1">美团流水线引擎：领取成功与执行开始之间还有窗口 <a class="header-anchor" href="#mei-tuan-liu-shui-xian-yin-qingling-qu-cheng-gong-yu-zhi-xing-kai-shi-zhi-jian-huan-you-chuang-kou" aria-label="Permalink to &quot;美团流水线引擎：领取成功与执行开始之间还有窗口&quot;">​</a></h2><p>美团的<a href="https://tech.meituan.com/2022/07/14/CICD-Pipeline.html" target="_blank" rel="noreferrer">流水线引擎建设实践</a>描述了决策、待领取、已调度等状态，以及乐观锁、领取 ACK 和队列补偿。文中的作业可能在 Worker 长暂停后被再次分配，因此恢复的旧 Worker 不能被默认视为仍拥有执行资格。</p><p>这个模式可用于检查本文转码任务的故障窗口：任务领取后尚未开始时崩溃，应该允许恢复；旧进程恢复后尝试发布，则应被当前 token 与源版本拒绝。外部转码服务已经接受的请求，不能只凭本地租约过期便确认没有执行，需要查询原任务或使用供应商支持的请求幂等机制。美团原文是 CI/CD 场景，本文借用的是状态与交付边界，没有将其直接当作视频处理实现。</p><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li><p>火山引擎官方文档：<a href="https://docs.volcengine.com/docs/video-on-demand/event-notification-faq?lang=zh" target="_blank" rel="noreferrer">视频点播：事件通知常见问题</a></p></li><li><p>美团技术团队：<a href="https://tech.meituan.com/2022/07/14/CICD-Pipeline.html" target="_blank" rel="noreferrer">工程效能 CI/CD 之流水线引擎的建设实践</a></p></li><li><p>腾讯云官方文档：<a href="https://cloud.tencent.com/document/product/266/33781" target="_blank" rel="noreferrer">云点播：回调设置</a></p></li><li><p>腾讯云官方文档：<a href="https://cloud.tencent.com/document/product/862/37049" target="_blank" rel="noreferrer">媒体处理：任务配置相关</a></p></li><li><p>Amazon S3：<a href="https://docs.aws.amazon.com/AmazonS3/latest/userguide/notification-how-to-event-types-and-destinations.html" target="_blank" rel="noreferrer">Event notification types and destinations</a></p></li><li><p>AWS Prescriptive Guidance：<a href="https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/transactional-outbox.html" target="_blank" rel="noreferrer">Transactional outbox pattern</a></p></li></ul>`,55))])}const k=i(p,[["render",c]]);export{f as __pageData,k as default};
